import{_ as e,o as t,c as i,a3 as s}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"xclang","text":"Cross-Compiling with Clang","tagline":"Six targets in every archive: Linux, Windows and macOS, each on x64 and arm64. Programs that need nothing but the OS.","actions":[{"theme":"brand","text":"What is xclang?","link":"./guide/what-is-xclang"},{"theme":"alt","text":"Quick Start","link":"./guide/quick-start"},{"theme":"alt","text":"Why xclang?","link":"./guide/why-xclang"}]},"features":[{"title":"Cross-Compiling","details":"A --target flag is all it takes. The sysroots, libc++ and lld for all six targets come with the toolchain.","link":"./guide/cross-compiling"},{"title":"Self-Contained Programs","details":"A program loads only what its OS has: glibc 2.17 or later, the Windows DLLs, or libSystem. Everything else is linked in.","link":"./design/hermeticity"},{"title":"Fast Compiles","details":"clang and lld are built with PGO and ThinLTO on every host, Windows included.","link":"./design/pgo#what-it-buys"},{"title":"C++20 Modules","details":"import std in CMake 3.28 or later, without experimental switches, and in Bazel.","link":"./features/modules"},{"title":"Every Build System","details":"CMake, Bazel, Meson, Make and cargo, with xclang from pixi, an archive, FetchContent or the Bazel registry.","link":"./guide/install"},{"title":"Reproducible Builds","details":"Every release is pinned by sha256. Bazel builds carry no absolute paths, so one cache serves every checkout.","link":"./design/bazel-module"}],"head":[["meta",{"property":"og:title","content":"clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/"}]]},"headers":[],"relativePath":"xclang/index.md","filePath":"en/xclang/index.md","lastUpdated":1791266105000}'),n={name:"xclang/index.md"};function l(o,a,r,d,c,p){return t(),i("div",null,[...a[0]||(a[0]=[s('<h2 id="beyond-the-release" tabindex="-1">Beyond the Release <a class="header-anchor" href="#beyond-the-release" aria-label="Permalink to &quot;Beyond the Release&quot;">​</a></h2><p>The cards above are what a release has today. xclang&#39;s vision goes further, the way rustup goes for Rust: every target, fetched when a build needs it, and vendor SDKs fetched from the vendor. None of the items below is in a release. The <a href="./design/roadmap">roadmap</a> has one row for each, with its status.</p><div class="capability warn"><div class="capability-meta"><span class="status-badge warn">Unreleased</span></div><p class="capability-title">The xclang command</p><p>Fetches Apple&#39;s and Microsoft&#39;s SDKs from the vendor, by a pinned version and digest. CI builds and tests it from <code>main</code> (<a href="./design/roadmap#xclang-command">roadmap</a>).</p></div><div class="capability warn"><div class="capability-meta"><span class="status-badge warn">Unreleased</span></div><p class="capability-title">MSVC-ABI targets</p><p>Windows x64 and arm64 with Microsoft&#39;s CRT and STL, fetched by the xclang command, from every host, with their sanitizers. CI builds and runs them from <code>main</code> (<a href="./design/roadmap#msvc">roadmap</a>).</p></div><div class="capability warn"><div class="capability-meta"><span class="status-badge warn">Unreleased</span></div><p class="capability-title">macOS targets from Linux and Windows</p><p>arm64 and x64 macOS programs from every host, with Apple&#39;s SDK fetched from Apple by the xclang command. CI builds them on Linux and Windows and runs them on Macs, from <code>main</code> (<a href="./design/roadmap#macos-any-host">roadmap</a>).</p></div><div class="capability note"><div class="capability-meta"><span class="status-badge note">Planned</span></div><p class="capability-title">Target archives</p><p>Targets beyond the six, each an archive that <code>xclang target add</code> fetches (<a href="./design/roadmap#target-archives">roadmap</a>).</p></div><div class="capability note"><div class="capability-meta"><span class="status-badge note">Planned</span></div><p class="capability-title">musl targets</p><p>Fully static Linux programs, for x64 and arm64 (<a href="./design/roadmap#musl">roadmap</a>).</p></div><div class="capability note"><div class="capability-meta"><span class="status-badge note">Considered</span></div><p class="capability-title">WebAssembly, Android, more Linux architectures</p><p>WASI targets, Android with the NDK of the user, and Linux beyond x64 and arm64 (<a href="./design/roadmap#targets">roadmap</a>).</p></div>',8)])])}const g=e(n,[["render",l]]);export{m as __pageData,g as default};
